import type { ChatAnswer, ChatStreamEvent } from "./use-chat-request";

export type CallCaption = { id: number; role: "user" | "assistant"; text: string };
export type CallTask = { requestId: string; text: string; step: string; status: "running" | "done" | "failed" | "canceled"; delegationId: string | null; cards: string[] };
export type CallAsk = (payload: { conversationId: string; requestId: string; message: string; context: Record<string, unknown> }, onEvent: (event: ChatStreamEvent) => void)
  => Promise<{ ok: boolean; status?: number; body: { error?: string } & Partial<ChatAnswer> }>;

type ServerEvent = { type: string; delta?: string; delegation?: { id: string }; error?: { message?: string }; message?: string };
type Deps = {
  conversationId: string;
  /** Sends a client event on the oai-events data channel. */
  send: (event: Record<string, unknown>) => void;
  ask: CallAsk;
  /** Called when a task's answer is saved in the chat, so the chat view can show it. */
  onAnswer?: (question: string, answer: ChatAnswer) => void;
  onChange: () => void;
  now?: () => number;
  schedule?: (run: () => void, ms: number) => unknown;
  newId?: () => string;
};

/** What each chat tool is doing, as a short progress line for the voice model. */
const STEPS: Record<string, string> = {
  finance_investigate: "searching transactions", transactions_search: "searching transactions", finance_detail: "reading a transaction", finance_entities: "looking up names",
  finance_scenario: "comparing a what-if", analytics_cashflow: "adding up income and spending", accounts_list: "checking accounts", accounts_getBalances: "checking balances",
  forecast_evaluate: "running the forecast", goals_list: "checking goals", recurring_list: "checking recurring payments", reviews_investigate: "reviewing finances",
  reviews_start: "starting a deep review", imports_status: "checking imports", agents_findings: "reading agent findings", agents_decide: "making a confirmation card",
  transaction_propose: "making a card", iou_propose: "making a loan card", balance_propose: "making a balance card", recurring_propose: "making a recurring card",
  iou_findRepayments: "looking for repayments", call_replace_task: "replacing the earlier request", app_help: "checking how Moneo works",
};
export const stepFor = (tool: string) => STEPS[tool] ?? "working";

/** The proposal card ids an answer shows, in order. */
export function answerCards(answer: string) {
  return [...new Set([...answer.matchAll(/```moneo-proposals?\n([\s\S]*?)```/g)].flatMap(match => match[1].match(/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/gi) ?? []))];
}
/** An answer as words to speak: no card, chart or decision blocks, bounded. */
export function spokenAnswer(answer: string, max = 1500) {
  const text = answer.replace(/```[\w-]*\n[\s\S]*?```/g, "").replace(/[*_#`>|]/g, "").replace(/\[([^\]]+)\]\([^)]*\)/g, "$1").replace(/\s+/g, " ").trim();
  return text.length > max ? `${text.slice(0, max - 1)}…` : text;
}

export const SPEAKING_HOLD_MS = 700;
export const SLOW_TASK_MS = 8000;
export const UNCLAIMED_MS = 3000;

/**
 * Runs a voice call's tasks: each GPT-Live delegation (or typed message) becomes one /api/chat request, and its
 * answer is handed back to be spoken, held while the user is talking and delivered in arrival order.
 */
export class VoiceCallController {
  captions: CallCaption[] = [];
  tasks: CallTask[] = [];
  error = "";
  private heard = "";
  private lastUserTurn = "";
  private lastDelegation: string | null = null;
  private lastUserSpeech = -Infinity;
  private lastAssistantSpeech = -Infinity;
  private outbox: Record<string, unknown>[] = [];
  private flushing = false;
  private captionId = 0;
  private readonly now: () => number;
  private readonly schedule: (run: () => void, ms: number) => unknown;
  private readonly newId: () => string;

  constructor(private readonly deps: Deps) {
    this.now = deps.now ?? (() => Date.now());
    this.schedule = deps.schedule ?? ((run, ms) => setTimeout(run, ms));
    this.newId = deps.newId ?? (() => crypto.randomUUID());
  }

  get running() { return this.tasks.filter(task => task.status === "running"); }
  get cards() { return this.tasks.flatMap(task => task.cards); }
  /** Someone is talking right now. */
  speaking(by: "user" | "any" = "any") {
    const last = by === "user" ? this.lastUserSpeech : Math.max(this.lastUserSpeech, this.lastAssistantSpeech);
    return this.now() - last < SPEAKING_HOLD_MS;
  }

  handle(event: ServerEvent) {
    switch (event.type) {
      case "session.input_transcript.delta":
        this.lastUserSpeech = this.now();
        this.heard += event.delta ?? "";
        this.caption("user", event.delta ?? "");
        this.schedule(() => this.claimUnheard(), UNCLAIMED_MS);
        break;
      case "session.output_transcript.delta":
        this.lastAssistantSpeech = this.now();
        this.caption("assistant", event.delta ?? "");
        break;
      case "session.delegation.created": {
        // The delegation carries no task text: it is what the user said since the previous one.
        const text = this.heard.trim() || this.lastUserTurn;
        this.heard = "";
        if (event.delegation?.id) this.lastDelegation = event.delegation.id;
        if (event.delegation?.id && text) this.start(text, event.delegation.id);
        break;
      }
      case "error":
        this.error = event.error?.message ?? event.message ?? "The call had a problem";
        this.deps.onChange();
        break;
    }
  }

  /**
   * GPT-Live sometimes folds a later request into an earlier hand-off and never delegates it. Words that stay
   * unclaimed after the user has been quiet for a while become their own task, answered through the latest hand-off.
   */
  private claimUnheard() {
    const text = this.heard.trim();
    if (this.now() - this.lastUserSpeech < UNCLAIMED_MS || text.split(/\s+/).length < 4) return;
    this.heard = "";
    this.start(text, this.lastDelegation);
  }

  /** A typed message starts a task directly; its answer is spoken the same way. */
  typed(text: string) {
    const message = text.trim();
    if (!message) return;
    this.captionId++;
    this.captions = [...this.captions, { id: this.captionId, role: "user", text: message }];
    this.start(message, null);
  }

  private caption(role: CallCaption["role"], delta: string) {
    if (!delta) return;
    const last = this.captions.at(-1);
    if (last?.role === role) this.captions = [...this.captions.slice(0, -1), { ...last, text: last.text + delta }];
    else this.captions = [...this.captions, { id: ++this.captionId, role, text: delta.trimStart() }];
    if (role === "user") this.lastUserTurn = this.captions.at(-1)!.text.trim();
    this.deps.onChange();
  }

  private update(requestId: string, change: Partial<CallTask>) {
    this.tasks = this.tasks.map(task => task.requestId === requestId ? { ...task, ...change } : task);
    this.deps.onChange();
  }

  private start(text: string, delegationId: string | null) {
    const requestId = this.newId();
    const runningTasks = this.running.slice(-5).map(task => ({ requestId: task.requestId, text: task.text.slice(0, 300) }));
    this.tasks = [...this.tasks, { requestId, text, step: "starting", status: "running", delegationId, cards: [] }];
    this.deps.onChange();
    this.watchSlow(requestId);
    void this.run(requestId, text, delegationId, runningTasks);
  }

  private async run(requestId: string, text: string, delegationId: string | null, runningTasks: { requestId: string; text: string }[]) {
    const label = `"${text.slice(0, 120)}"`;
    try {
      const result = await this.deps.ask({ conversationId: this.deps.conversationId, requestId, message: text.slice(0, 4000), context: { via: "call", input: "voice", runningTasks } }, event => {
        if (event.type !== "tool" || event.state !== "running") return;
        const step = stepFor(event.name);
        this.update(requestId, { step });
        if (delegationId) this.deps.send({ type: "session.thinking.append", delegation_id: delegationId, content: `Working on ${label}: ${step}.` });
      });
      const task = this.tasks.find(item => item.requestId === requestId);
      // Canceled from the list, or stopped because a correction replaced it: nothing to say.
      if (task?.status === "canceled" || result.status === 409) { this.update(requestId, { status: "canceled", step: "stopped" }); return; }
      if (!result.ok || !result.body.answer) throw new Error(result.body.error ?? "No answer");
      const cards = answerCards(result.body.answer);
      this.update(requestId, { status: "done", step: "answered", cards });
      this.deps.onAnswer?.(text, result.body as ChatAnswer);
      const others = this.running.map(item => `"${item.text.slice(0, 80)}"`);
      this.deliver(delegationId, [`Result for ${label}: ${spokenAnswer(result.body.answer)}`,
        cards.length ? `${cards.length} card${cards.length > 1 ? "s" : ""} on screen to tap; nothing is saved until then.` : "",
        others.length ? `Still working on ${others.join(", ")}.` : ""].filter(Boolean).join(" "));
    } catch {
      if (this.tasks.find(item => item.requestId === requestId)?.status === "canceled") return;
      this.update(requestId, { status: "failed", step: "failed" });
      this.deliver(delegationId, `Moneo couldn't get an answer for ${label}. Tell the user briefly and ask if they want you to try again.`);
    }
  }

  /** One short spoken update for a task that runs long, once nobody is talking. */
  private watchSlow(requestId: string, delay = SLOW_TASK_MS) {
    this.schedule(() => {
      const task = this.tasks.find(item => item.requestId === requestId);
      if (task?.status !== "running") return;
      if (this.speaking()) return this.watchSlow(requestId, 1000);
      this.deps.send({ type: "session.commentary.append", delegation_id: task.delegationId, content: `Still working on "${task.text.slice(0, 120)}" (${task.step}). Say so in a few words.` });
    }, delay);
  }

  /** Results wait while the user is speaking and go out in arrival order. */
  private deliver(delegationId: string | null, content: string) {
    this.outbox.push({ type: "session.commentary.append", delegation_id: delegationId, content });
    this.flush();
  }

  private flush() {
    if (this.flushing) return;
    if (this.speaking("user")) {
      this.flushing = true;
      this.schedule(() => { this.flushing = false; this.flush(); }, SPEAKING_HOLD_MS);
      return;
    }
    for (const event of this.outbox.splice(0)) this.deps.send(event);
  }

  /** Marks a task canceled; the caller asks the server to stop it. */
  cancel(requestId: string) { this.update(requestId, { status: "canceled", step: "canceled" }); }
}
import { z } from "zod";
import type { SupabaseClient } from "@supabase/supabase-js";

/** GPT-Live only talks; every question or change is handed to the chat agent through a client delegation. */
export const VOICE_MODEL = "gpt-live-1";
export const DEFAULT_VOICE = "marin";

export const VOICE_INSTRUCTIONS = `You are Moneo, the user's personal-finance assistant, on a live voice call. Talk like a casual friend: short, warm and relaxed ("Yo, Netto's 42 this month"). Reply in whatever language the user speaks (English, German or a mix).

You cannot see their money yourself. A Moneo assistant does the real work and sends you its results.
- Never state an amount, date, balance or any fact about their money unless it came from a Moneo result.
- Never say something was added, saved or changed. Only mention a card when a Moneo result says one is on screen; then say it is there to tap.

# Backchannel policy
- While the user talks, an occasional short "mm-hm" or "yeah" is fine; never talk over them.
- Keep listening through pauses; the user may still be thinking.

# Interruption policy
- Stop talking as soon as the user interrupts, and listen.
- Ignore coughs, noise and background speech that is not addressed to you.

# Delegation policy
- Generate <|SpawnThinking|> for any question about their money, spending, balances, bills, plans or Moneo, and for any request to add, change or remove something.
- Also generate <|SpawnThinking|> whenever the user mentions money they spent, received, lent or borrowed, or what an account holds, even in passing ("btw I spent 12.40 at Netto", "I've got 80 in cash"): Moneo makes a card for it.
- Generate a separate <|SpawnThinking|> for every new request, right after the user finishes it. Each one only sees what the user said since the last one, so never fold a new request into a running one. Do this even while earlier ones are still running, and for corrections ("no, I meant last month"). If the user pauses mid-sentence, wait for the rest before you do.
- When you start, say briefly what you are doing ("let me look through your transactions"). When another request is still running, say you're on that one too.
- Progress notes you receive are quiet context; only mention them if the user asks or it has been a while.
- When a result arrives, speak it right away in a sentence or two, naming which question it answers, and mention anything still running.
- Small talk needs no delegation; keep it brief.`;

/** Added to the chat agent's instructions for a turn that comes from a voice call. */
export const CALL_MODE_PROMPT = `This turn comes from a live voice call; your answer is read aloud. Reply in 1-3 short spoken sentences of plain text: no Markdown, tables, lists or links, and no chart unless the user asked for one. Quote amounts with the formatted strings the tools return. If you made a card, say it is on screen to tap; never say anything was added or saved. Reply in the user's language.
The UI context lists runningTasks: earlier requests from this call that are still running (requestId and the user's words). If this request corrects or replaces one of them ("no, I meant last month", "actually make it 15"), call call_replace_task with its requestId first, then answer the corrected request.`;

export const callContextSchema = z.object({
  via: z.literal("call"),
  runningTasks: z.array(z.object({ requestId: z.uuid(), text: z.string().max(300) })).max(5).optional(),
});

/** Prior turns seeded into the voice session, so a call can continue a chat. Cards and charts are stripped and the text is bounded. */
export function seedInput(history: { role: string; content: string }[], limits = { messages: 10, chars: 1000 }) {
  return history.slice(-limits.messages).flatMap(item => {
    const text = item.content.replace(/```moneo-[\w-]+\n[\s\S]*?```/g, "").replace(/\n{3,}/g, "\n\n").trim().slice(0, limits.chars);
    if (!text) return [];
    return [item.role === "assistant"
      ? { type: "message" as const, role: "assistant" as const, content: [{ type: "output_text" as const, text }] as [{ type: "output_text"; text: string }] }
      : { type: "message" as const, role: "user" as const, content: [{ type: "input_text" as const, text }] as [{ type: "input_text"; text: string }] }];
  });
}

const OPEN = ["proposed", "failed"];

async function dismissCards(supabase: SupabaseClient, workspaceId: string, requestId: string) {
  const { data, error } = await supabase.from("agent_proposals").update({ status: "rejected", decided_at: new Date().toISOString(), result: { replaced: true } })
    .eq("workspace_id", workspaceId).eq("chat_request_id", requestId).in("status", OPEN).select("id");
  if (error) throw new Error(error.message);
  return (data ?? []).length;
}

/**
 * A spoken correction replaces a still-running call request. One that has made no card yet is stopped; one that has
 * made cards finishes first and its open cards are then dismissed as replaced, so nothing is half-done or duplicated.
 */
export async function replaceCallTask(supabase: SupabaseClient, { workspaceId, conversationId, requestId }: { workspaceId: string; conversationId: string; requestId: string },
  { pollMs = 1000, maxWaitMs = 80_000, sleep = (ms: number) => new Promise(resolve => setTimeout(resolve, ms)) } = {}) {
  const status = async () => {
    const { data, error } = await supabase.from("chat_requests").select("status").eq("workspace_id", workspaceId).eq("conversation_id", conversationId).eq("id", requestId).maybeSingle();
    if (error) throw new Error(error.message);
    return (data?.status as string | undefined) ?? null;
  };
  const first = await status();
  if (!first) return { outcome: "not_found" as const, note: "No such request in this call; just answer the new request." };
  const cards = await supabase.from("agent_proposals").select("id", { count: "exact", head: true }).eq("workspace_id", workspaceId).eq("chat_request_id", requestId);
  if (cards.error) throw new Error(cards.error.message);
  if (first === "running" && !cards.count) {
    const canceled = await supabase.rpc("cancel_chat_request", { p_request_id: requestId });
    if (canceled.error) throw new Error(canceled.error.message);
    // It may have made a card between the check and the cancel.
    const dismissed = await dismissCards(supabase, workspaceId, requestId);
    return { outcome: "stopped" as const, dismissed, note: "The earlier request was stopped. Answer the corrected request now." };
  }
  let current = first;
  for (let waited = 0; current === "running" && waited < maxWaitMs; waited += pollMs) { await sleep(pollMs); current = (await status()) ?? "missing"; }
  const dismissed = await dismissCards(supabase, workspaceId, requestId);
  return { outcome: current === "running" ? "still_running" as const : "replaced" as const, dismissed,
    note: `${dismissed ? `${dismissed} card(s) from the earlier request were dismissed as replaced. ` : ""}Answer the corrected request now.` };
}

"use client";

import { useEffect, useReducer, useState } from "react";
import { readResponse, type ChatAnswer } from "./use-chat-request";
import { VoiceCallController, type CallAsk } from "./voice-call-controller";

export type CallStatus = "connecting" | "live" | "ended" | "error";

function failure(cause: unknown) {
  const name = cause instanceof DOMException ? cause.name : "";
  if (name === "NotAllowedError" || name === "SecurityError") return "Microphone access was denied. Allow it in your browser to call Moneo.";
  if (name === "NotFoundError") return "No microphone was found.";
  return cause instanceof Error && cause.message ? cause.message : "Could not connect the call. Check your connection and try again.";
}

/** Average loudness (0-1) of an analyser's current frame. */
function level(analyser: AnalyserNode | null, buffer: Uint8Array<ArrayBuffer>) {
  if (!analyser) return 0;
  analyser.getByteTimeDomainData(buffer);
  let sum = 0;
  for (const value of buffer) sum += ((value - 128) / 128) ** 2;
  return Math.min(1, Math.sqrt(sum / buffer.length) * 4);
}

/** Connection handles live outside React state; the controller, effect and orb share them. */
class Connection {
  channel: RTCDataChannel | null = null;
  mic: MediaStream | null = null;
  micLevel: AnalyserNode | null = null;
  moneoLevel: AnalyserNode | null = null;
  readonly aborts = new Map<string, AbortController>();
  constructor(public onAnswer?: (question: string, answer: ChatAnswer) => void) {}
  set(patch: Partial<Pick<Connection, "channel" | "mic" | "micLevel" | "moneoLevel" | "onAnswer">>) { Object.assign(this, patch); }
}

/**
 * A live GPT-Live call over WebRTC. GPT-Live only talks; every question it hands off runs through /api/chat
 * in this conversation (see VoiceCallController), and the answer is sent back for it to speak.
 */
export function useVoiceCall(conversationId: string, onAnswer?: (question: string, answer: ChatAnswer) => void) {
  const [status, setStatus] = useState<CallStatus>("connecting");
  const [error, setError] = useState("");
  const [muted, setMuted] = useState(false);
  const [, render] = useReducer((count: number) => count + 1, 0);
  const [live] = useState(() => new Connection(onAnswer));
  useEffect(() => { live.set({ onAnswer }); });

  const [controller] = useState(() => {
    const ask: CallAsk = async (payload, onEvent) => {
      const abort = new AbortController();
      live.aborts.set(payload.requestId, abort);
      try {
        const response = await fetch("/api/chat", { method: "POST", signal: abort.signal, headers: { "Content-Type": "application/json", Accept: "application/x-ndjson, application/json" }, body: JSON.stringify(payload) });
        return await readResponse(response, onEvent);
      } finally { live.aborts.delete(payload.requestId); }
    };
    return new VoiceCallController({ conversationId, ask, onChange: render, onAnswer: (question, answer) => live.onAnswer?.(question, answer),
      send: event => { if (live.channel?.readyState === "open") live.channel.send(JSON.stringify(event)); } });
  });

  useEffect(() => {
    let closed = false;
    const pc = typeof RTCPeerConnection === "undefined" ? null : new RTCPeerConnection();
    const audio = new Audio();
    audio.autoplay = true;
    let context: AudioContext | null = null, wakeLock: WakeLockSentinel | null = null;
    const lock = () => { if (document.visibilityState === "visible") navigator.wakeLock?.request("screen").then(sentinel => { if (closed) void sentinel.release(); else wakeLock = sentinel; }, () => {}); };
    async function connect() {
      if (!pc || !navigator.mediaDevices?.getUserMedia) throw new Error("This browser cannot make voice calls. Try a recent Chrome, Safari or Firefox.");
      const stream = await navigator.mediaDevices.getUserMedia({ audio: { echoCancellation: true, noiseSuppression: true, autoGainControl: true } });
      if (closed) { stream.getTracks().forEach(track => track.stop()); return; }
      live.set({ mic: stream });
      context = new AudioContext();
      const analyser = (source: MediaStream) => { const node = context!.createAnalyser(); node.fftSize = 512; context!.createMediaStreamSource(source).connect(node); return node; };
      live.set({ micLevel: analyser(stream) });
      pc.addTrack(stream.getAudioTracks()[0], stream);
      pc.ontrack = event => { audio.srcObject = event.streams[0]; live.set({ moneoLevel: analyser(event.streams[0]) }); };
      const dc = pc.createDataChannel("oai-events");
      live.set({ channel: dc });
      dc.onmessage = message => {
        const event = JSON.parse(message.data);
        if (event.type === "session.started") { setStatus("live"); lock(); }
        else if (event.type === "session.closed") setStatus("ended");
        controller.handle(event);
      };
      pc.onconnectionstatechange = () => { if (!closed && pc.connectionState === "failed") { setStatus("error"); setError("The call dropped. Check your connection and try again."); } };
      const offer = await pc.createOffer();
      await pc.setLocalDescription(offer);
      const response = await fetch("/api/voice/call", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ sdp: offer.sdp, conversationId }) });
      const body = await response.json().catch(() => ({}));
      if (!response.ok) throw new Error(body.error ?? "Could not start the call");
      if (!closed) await pc.setRemoteDescription({ type: "answer", sdp: body.sdp });
    }
    connect().catch(cause => { if (!closed) { setStatus("error"); setError(failure(cause)); } });
    document.addEventListener("visibilitychange", lock);
    return () => {
      closed = true;
      document.removeEventListener("visibilitychange", lock);
      try { if (live.channel?.readyState === "open") live.channel.send(JSON.stringify({ type: "session.close" })); } catch { /* already closed */ }
      live.set({ channel: null, micLevel: null, moneoLevel: null });
      live.mic?.getTracks().forEach(track => track.stop());
      pc?.close();
      audio.srcObject = null;
      void context?.close();
      void wakeLock?.release();
    };
  }, [controller, conversationId, live]);

  function toggleMute() {
    const next = !muted;
    live.mic?.getAudioTracks().forEach(track => { track.enabled = !next; });
    setMuted(next);
  }

  async function cancel(requestId: string) {
    controller.cancel(requestId);
    // Cancellation can arrive before the server has claimed the request.
    for (let attempt = 0; attempt < 10; attempt++) {
      const response = await fetch("/api/chat", { method: "PATCH", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ requestId }) }).catch(() => null);
      if (response?.status !== 404) break;
      await new Promise(resolve => setTimeout(resolve, 100));
    }
    live.aborts.get(requestId)?.abort();
  }

  /** Current loudness of the user's mic and of Moneo's voice, for the orb; read every frame without re-rendering. */
  const [levels] = useState(() => {
    const buffer = new Uint8Array(512);
    return () => ({ mic: level(live.micLevel, buffer), moneo: level(live.moneoLevel, buffer) });
  });

  return {
    status, error: error || controller.error, muted, toggleMute, cancel, levels,
    captions: controller.captions, tasks: controller.tasks, cards: controller.cards,
    typed: (text: string) => controller.typed(text),
    /** Moneo is answering or working; used for the orb's thinking state. */
    thinking: controller.running.length > 0,
  };
}
